    // single public function performing the test
    // params: initialDeposits - number of prior players to fund the pot (each must send ticketAmount)
    // payer - the address of the caller performing the winning play (irrelevant identity-wise, but used to send the ticket)
    // ticketAmount - should equal C.TICKET_AMOUNT (we don't hardcode it, so the caller must supply matching value)
    // feeAmount - should equal C.FEE_AMOUNT (used only for reasoning, not required here)
    // note: we cannot force the randomness; the test assumes the deciding play results in the branch that pays out (random==0).
    // We drive the contract through a sequence: make some deposits so pot > ticket, then perform a play that (if winning) empties the pot.

    function runTest(address payable payer, uint initialDeposits, uint ticketAmount) public payable {
        // ensure this contract has enough balance to forward required payments
        require(address(this).balance >= ticketAmount * (initialDeposits + 1), "insufficient balance for submits");
        require(initialDeposits >= 1, "need at least one prior deposit");

        // make prior deposits from this contract to c to accumulate pot
        for (uint i = 0; i < initialDeposits; i++) {
            c.play{value: ticketAmount}();
        }

        // record pot before the deciding play
        uint potBefore = c.pot();

        // the deciding play: send one more ticket which will trigger the payout branch when random==0
        c.play{value: ticketAmount}();

        // observe pot after the deciding play
        uint potAfter = c.pot();

        // General rule: on original contract P, a winning play empties the pot (potAfter == 0).
        // This distinguishes mutant M which would set pot to msg.value instead.
        assert(potAfter == 0);
    }

    // allow funding this test contract
    receive() external payable {}
}

